def has_property(item, pid):
    return pid in item.claims


def add_string_claim(item, pid, value, summary):
    claim = pywikibot.Claim(repo, pid)
    claim.setTarget(value)
    item.addClaim(claim, summary=summary)


def process_item(qid):
    item = pywikibot.ItemPage(repo, qid)

    try:
        item.get()
    except Exception as e:
        print(f"{qid}: failed to load ({e})")
        return

    print(f"Processing {qid}")

    # --- P3321 ---
    if not has_property(item, "P3321"):
        print(f"  Missing P3321 → adding")
        try:
            add_string_claim(
                item,
                "P3321",
                "VALUE_FOR_P3321",  # <-- YOU MUST DEFINE THIS
                "Adding missing P3321"
            )
        except Exception as e:
            print(f"  Failed to add P3321: {e}")
    else:
        print(f"  P3321 already exists")

    # --- P2521 ---
    if not has_property(item, "P2521"):
        print(f"  Missing P2521 → adding")
        try:
            add_string_claim(
                item,
                "P2521",
                "VALUE_FOR_P2521",  # <-- YOU MUST DEFINE THIS
                "Adding missing P2521"
            )
        except Exception as e:
            print(f"  Failed to add P2521: {e}")
    else:
        print(f"  P2521 already exists")


def main():
    for qid in QIDS:
        process_item(qid)
        time.sleep(1)  # respect rate limits


if __name__ == "__main__":
    main()